  'corridas.v.pieTrabajo4': { es: 'trabajo', en: 'work' },
  'corridas.v.pieTrabajo5': { es: ', todos los demás; lo que pasa entre el fin de un paso y el arranque del siguiente es un tramo aparte, rayado, que no se le cobra a ninguno. Las ejecuciones anteriores a esa marca salen', en: ', all the others; what happens between the end of one step and the start of the next is a separate, striped stretch that is charged to none. Runs before that mark come out' },
  'corridas.v.pieTrabajo6': { es: 'estimadas por diferencia', en: 'estimated by difference' },
  'corridas.v.pieTrabajo7': { es: ' y lo dicen; un paso de menos de un minuto se dibuja como una raya: se marcó junto con el anterior.', en: ' and say so; a step under one minute is drawn as a line: it was marked together with the previous one.' },
